package info.u_team.music_player.gui.settings;
import static info.u_team.music_player.init.MusicPlayerLocalization.getTranslation;
import info.u_team.music_player.gui.util.GuiTextCompat;import info.u_team.music_player.musicplayer.MusicPlayerManager;import info.u_team.music_player.musicplayer.settings.Settings;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.Renderable;import net.minecraft.client.gui.components.events.GuiEventListener;import net.minecraft.client.gui.narration.NarratableEntry;import net.minecraft.client.gui.narration.NarrationElementOutput;
final class MiniPlayerLayoutWidget implements Renderable,GuiEventListener,NarratableEntry{private final int sw,sh;private int x,y,width,height;private boolean resizing,dragging,focused;private double ox,oy;MiniPlayerLayoutWidget(int sw,int sh){this.sw=sw;this.sh=sh;final Settings s=MusicPlayerManager.getSettingsManager().getSettings();width=Math.clamp(s.getMiniPlayerWidth(),80,Math.max(80,sw-6));height=Math.max(30,Math.round(width*35F/120F));x=s.getMiniPlayerX()<0?(sw-width)/2:Math.clamp(s.getMiniPlayerX(),3,Math.max(3,sw-width-3));y=s.getMiniPlayerY()<0?(sh-height)/2:Math.clamp(s.getMiniPlayerY(),3,Math.max(3,sh-height-3));}@Override public void render(GuiGraphics g,int mx,int my,float pt){g.fill(x,y,x+width,y+height,0xE521262C);g.fill(x,y,x+width,y+1,0xFF75E0B5);g.fill(x,y+height-1,x+width,y+height,0xFF75E0B5);GuiTextCompat.draw(g,Minecraft.getInstance().font,getTranslation("gui.layout.track"),x+6,y+5,0xFFD166,false);GuiTextCompat.draw(g,Minecraft.getInstance().font,getTranslation("gui.layout.artist"),x+8,y+16,0xD86D1C,false);GuiTextCompat.draw(g,Minecraft.getInstance().font,"|<   >   >|   +1   ☆",x+6,y+height-11,0xFFFFFF,false);g.fill(x+width-7,y+height-7,x+width,y+height,0xFFFFCC66);}@Override public boolean mouseClicked(double mx,double my,int b){final Settings s=MusicPlayerManager.getSettingsManager().getSettings();if(b!=0||s.isMiniPlayerLocked()||!isMouseOver(mx,my))return false;resizing=mx>=x+width-10&&my>=y+height-10;dragging=!resizing;ox=mx-x;oy=my-y;return true;}@Override public boolean mouseDragged(double mx,double my,int b,double dx,double dy){if(b!=0)return false;if(resizing){width=Math.clamp((int)mx-x,80,Math.min(640,sw-x-3));height=Math.max(30,Math.round(width*35F/120F));return true;}if(dragging){x=Math.clamp((int)(mx-ox),3,Math.max(3,sw-width-3));y=Math.clamp((int)(my-oy),3,Math.max(3,sh-height-3));return true;}return false;}@Override public boolean mouseReleased(double mx,double my,int b){if(b!=0||(!dragging&&!resizing))return false;final Settings s=MusicPlayerManager.getSettingsManager().getSettings();if(s.isMiniPlayerSnapToEdges()){if(x<16)x=3;if(y<16)y=3;if(sw-x-width<16)x=sw-width-3;if(sh-y-height<16)y=sh-height-3;}s.setMiniPlayerLayout(x,y,width);dragging=false;resizing=false;return true;}@Override public boolean isMouseOver(double mx,double my){return mx>=x&&mx<x+width&&my>=y&&my<y+height;}@Override public void setFocused(boolean v){focused=v;}@Override public boolean isFocused(){return focused;}@Override public NarrationPriority narrationPriority(){return focused?NarrationPriority.FOCUSED:NarrationPriority.NONE;}@Override public void updateNarration(NarrationElementOutput o){}}
